from pathlib import Path
import re

p=Path('index.html')
s=p.read_text(encoding='utf-8')

def rep(old,new,label):
    global s
    if old not in s:
        raise SystemExit(f'bloco não encontrado: {label}')
    s=s.replace(old,new,1)

def sub(pattern,new,label,flags=re.S):
    global s
    s2,n=re.subn(pattern,new,s,count=1,flags=flags)
    if n!=1:
        raise SystemExit(f'bloco regex não encontrado/ambíguo: {label} ({n})')
    s=s2

