sub(r'''    function renderAdminSimulationFields\(\)\{.*?\n    \}\n\n    function adminPlanWindow''', '''    function renderAdminSimulationFields(){\n      const enabled=Boolean(el('adminSimulationEnabled')?.checked);\n      const fields=el('adminSimulationFields');\n      if(fields) fields.hidden=!enabled;\n      const occurrence=el('adminSimulationMode')?.value==='weekday_occurrence';\n      if(el('adminSimulationWeekdayField')) el('adminSimulationWeekdayField').hidden=!occurrence;\n      if(el('adminSimulationIntervalHelp')){\n        el('adminSimulationIntervalHelp').textContent=occurrence\n          ? '1 = toda semana nos dias marcados; 2 = a cada 2 semanas nos dias marcados.'\n          : 'Ex.: 15 = um simulado a cada 15 dias corridos.';\n      }\n      const type=el('adminSimulationType')?.value||'full';\n      if(el('adminSimulationTypeHelp')){\n        el('adminSimulationTypeHelp').textContent=type==='subject'\n          ? 'Os simulados alternam automaticamente entre as matérias cadastradas.'\n          : 'O simulado completo considera o concurso inteiro.';\n      }\n      syncAdminSimulationAllWeekdays();\n    }\n\n    function adminPlanWindow''','render sim fields')

sub(r'''    function adminSimulationDates\(draft,window\)\{.*?\n    \}\n\n    function adminSubjectQueues''', '''    function adminSimulationDates(draft,window){\n      const dates=[];\n      if(!draft.simulationEnabled) return dates;\n      const all=adminDatesInWindow(window);\n      const interval=Math.max(1,draft.simulationInterval);\n      if(draft.simulationMode==='weekday_occurrence'){\n        const chosen=new Set((Array.isArray(draft.simulationWeekdays)&&draft.simulationWeekdays.length\n          ? draft.simulationWeekdays\n          : [draft.simulationWeekday??6]).map(Number));\n        const firstMonday=new Date(window.start);\n        firstMonday.setDate(firstMonday.getDate()-((firstMonday.getDay()+6)%7));\n        all.forEach(date=>{\n          const day=(date.getDay()+6)%7;\n          if(!chosen.has(day)) return;\n          const weekIndex=Math.floor((calendarDaysBetween(firstMonday,date)-1)/7);\n          if(weekIndex%interval===0) dates.push(new Date(date));\n        });\n      }else{\n        all.forEach((date,index)=>{\n          if((index+1)%interval===0) dates.push(new Date(date));\n        });\n      }\n      return dates;\n    }\n\n    function adminSubjectQueues''','simulation dates')

rep("""      preview.simDates.forEach(date=>{\n        const start=timeToMinutes(draft.simulationStart);\n        const day=(date.getDay()+6)%7;\n        tasks.push({\n          id:cryptoId(),\n          day,\n          date:localDateKey(date),\n          cycleOrder:tasks.length,\n          start:minutesToTime(start),\n          end:minutesToTime(start+draft.simulationMinutes),\n          subject:'Simulado',\n          activity:`Simulado completo - ${draft.goal}`,\n          type:'Simulado',\n          notes:'Dia reservado exclusivamente para a realização do simulado.',\n          done:false\n        });\n      });\n""","""      preview.simDates.forEach((date,simulationIndex)=>{\n        const start=timeToMinutes(draft.simulationStart);\n        const day=(date.getDay()+6)%7;\n        const bySubject=draft.simulationType==='subject';\n        const simulationSubject=bySubject&&draft.subjects.length\n          ? String(draft.subjects[simulationIndex%draft.subjects.length].name||'Matéria').trim()\n          : '';\n        tasks.push({\n          id:cryptoId(),\n          day,\n          date:localDateKey(date),\n          cycleOrder:tasks.length,\n          start:minutesToTime(start),\n          end:minutesToTime(start+draft.simulationMinutes),\n          subject:bySubject?`Simulado - ${simulationSubject}`:'Simulado completo',\n          activity:bySubject?`Simulado por matéria - ${simulationSubject}`:`Simulado completo - ${draft.goal}`,\n          type:bySubject?'Simulado por matéria':'Simulado completo',\n          notes:bySubject\n            ? `Dia reservado exclusivamente para simulado da matéria ${simulationSubject}.`\n            : 'Dia reservado exclusivamente para a realização do simulado completo.',\n          done:false\n        });\n      });\n""",'build sim tasks')

