insert_before="""    function pdfBuildAdminIntroPageContent(pageIndex,pageCount){\n"""
police_helpers="""    function pdfSelectedThemeKey(){\n      return state.adminPersonalization?.pdfTheme||state.adminPdfTheme||'premium_masculino';\n    }\n\n    function pdfIsPoliceTheme(){\n      return pdfSelectedThemeKey().startsWith('policial_');\n    }\n\n    function pdfDrawPoliceShield(commands,x,y,size=46){\n      const w=size*.78;\n      const top=y+size;\n      const mid=y+size*.42;\n      const bottom=y;\n      pdfLine(commands,x-w/2,top,x+w/2,top,PDF_COLORS.cyan,1.7);\n      pdfLine(commands,x-w/2,top,x-w*.43,mid,PDF_COLORS.cyan,1.7);\n      pdfLine(commands,x-w*.43,mid,x,bottom,PDF_COLORS.cyan,1.7);\n      pdfLine(commands,x,bottom,x+w*.43,mid,PDF_COLORS.cyan,1.7);\n      pdfLine(commands,x+w*.43,mid,x+w/2,top,PDF_COLORS.cyan,1.7);\n      pdfLine(commands,x-w*.24,y+size*.63,x+w*.24,y+size*.63,PDF_COLORS.gold,1.5);\n      pdfLine(commands,x,y+size*.78,x,y+size*.46,PDF_COLORS.gold,1.5);\n      pdfLine(commands,x-w*.17,y+size*.73,x+w*.17,y+size*.51,PDF_COLORS.gold,1.2);\n      pdfLine(commands,x+w*.17,y+size*.73,x-w*.17,y+size*.51,PDF_COLORS.gold,1.2);\n      pdfText(commands,x-w*.30,y+size*.15,'MPC',7.2,true,PDF_COLORS.cyan,'center',w*.60);\n    }\n\n    function pdfDrawThemeIllustration(commands,variant='header'){\n      if(!pdfIsPoliceTheme()) return;\n      const {width,height}=PDF_PAGE;\n      const landscape=width>height;\n      if(variant==='intro-body'){\n        const cx=landscape?width-112:width-92;\n        const cy=landscape?height-238:height-205;\n        pdfDrawPoliceShield(commands,cx,cy,landscape?84:72);\n        pdfLine(commands,cx-58,cy-16,cx-28,cy-16,PDF_COLORS.line,2);\n        pdfLine(commands,cx+28,cy-16,cx+58,cy-16,PDF_COLORS.line,2);\n        return;\n      }\n      pdfDrawPoliceShield(commands,width-(landscape?72:58),height-72,44);\n    }\n\n    function pdfBuildAdminLandscapeIntroPageContent(pageIndex,pageCount){\n      const commands=[];\n      const {width,height,margin}=PDF_PAGE;\n      const student=state.studentName||'o aluno';\n      const data=state.adminPersonalization||{};\n      pdfRect(commands,0,0,width,height,PDF_COLORS.white);\n      pdfRect(commands,0,height-82,width,82,PDF_COLORS.navy);\n      pdfRect(commands,margin,height-59,7,34,PDF_COLORS.gold);\n      pdfText(commands,margin+19,height-38,'CRONOGRAMA PERSONALIZADO',21,true,PDF_COLORS.white);\n      pdfText(commands,margin+19,height-60,'Prof. Lucas MPC',10.5,true,PDF_COLORS.cyan);\n      pdfDrawThemeIllustration(commands,'header');\n\n      const leftX=margin;\n      const leftW=width*.55-margin-12;\n      const rightX=width*.58;\n      const rightW=width-margin-rightX;\n      pdfText(commands,leftX,height-119,'CRIADO ESPECIFICAMENTE PARA',14,true,PDF_COLORS.navy);\n      pdfDrawWrapped(commands,student,leftX,height-151,leftW,20,true,PDF_COLORS.goldDark,2,23);\n      const notice=`Planejamento individual elaborado para ${student}, considerando disponibilidade, dificuldades, período até a prova, material, nível da prova, concorrência e demais critérios informados na área administrativa.`;\n      pdfDrawWrapped(commands,notice,leftX,height-205,leftW,10.2,false,PDF_COLORS.text,6,13.5);\n\n      const periodStart=data.startDate?new Date(`${data.startDate}T12:00:00`).toLocaleDateString('pt-BR'):'Não informado';\n      const periodEnd=data.endDate?new Date(`${data.endDate}T12:00:00`).toLocaleDateString('pt-BR'):'Não informado';\n      pdfRect(commands,rightX,height-242,rightW,130,PDF_COLORS.soft,PDF_COLORS.line,.8);\n      pdfText(commands,rightX+14,height-135,'RESUMO DO PLANEJAMENTO',10.5,true,PDF_COLORS.navy);\n      const summary=[\n        `Período: ${periodStart} a ${periodEnd}`,\n        `Disponibilidade: ${state.hoursPerDay||0} hora(s) por dia`,\n        `Matérias: ${(state.subjects||[]).length}`,\n        data.simulationCount?`Simulados reservados: ${data.simulationCount}`:'Simulados: não programados'\n      ];\n      summary.forEach((item,index)=>pdfText(commands,rightX+14,height-160-index*19,pdfWrapText(item,rightW-28,9,1,false)[0],9,false,PDF_COLORS.muted));\n      pdfDrawThemeIllustration(commands,'intro-body');\n\n      pdfRect(commands,leftX,133,leftW,84,PDF_COLORS.pendingSoft,PDF_COLORS.gold,.8);\n      pdfDrawWrapped(commands,`Este cronograma é exclusivo de ${student}. Não reutilize sem considerar uma nova rotina, disponibilidade e objetivo.`,leftX+13,190,leftW-26,10.2,true,PDF_COLORS.navy,4,14);\n      pdfText(commands,leftX,108,'Use o Gerador MPC para criar um planejamento adequado à sua realidade.',9.5,true,PDF_COLORS.navy);\n\n      pdfLine(commands,margin,78,width-margin,78,PDF_COLORS.gold,1.1);\n      pdfText(commands,margin,63,'Documento personalizado - Prof. Lucas MPC',8.4,true,PDF_COLORS.navy);\n      pdfText(commands,width-margin-92,63,`Página ${pageIndex+1} de ${pageCount}`,8,false,PDF_COLORS.muted,'right',92);\n      const button=pdfDrawConfiguredButton(commands);\n      return {content:commands.join('\\n'),button};\n    }\n\n"""
