# Troca o antigo formato linear por calendário semanal real.
sub(r'''    function pdfPrepareDaysStyle\(\)\{.*?\n    \}\n\n    function pdfPrepareByStyle''', '''    function pdfPrepareDaysStyle(){\n      const tasksByDate=new Map();\n      pdfSortedTasks().forEach(task=>{\n        if(!task.date) return;\n        if(!tasksByDate.has(task.date)) tasksByDate.set(task.date,[]);\n        tasksByDate.get(task.date).push(task);\n      });\n      let dates=state.adminGenerated?pdfAdminCalendarDates():[];\n      if(!dates.length){\n        dates=[...tasksByDate.keys()].sort().map(dateFromKey).filter(Boolean);\n      }\n      if(!dates.length) return [{weekIndex:0,items:[]}];\n      const planIndex=new Map(dates.map((date,index)=>[localDateKey(date),index]));\n      const first=new Date(dates[0]);\n      first.setDate(first.getDate()-((first.getDay()+6)%7));\n      const last=new Date(dates.at(-1));\n      last.setDate(last.getDate()+(6-((last.getDay()+6)%7)));\n      const pages=[];\n      let cursor=new Date(first);\n      let weekIndex=0;\n      while(cursor<=last){\n        const items=[];\n        for(let col=0;col<7;col++){\n          const date=addCalendarDays(cursor,col);\n          const key=localDateKey(date);\n          items.push({\n            key,date,\n            inRange:planIndex.has(key),\n            planIndex:planIndex.has(key)?planIndex.get(key):-1,\n            tasks:tasksByDate.get(key)||[]\n          });\n        }\n        pages.push({weekIndex,items});\n        cursor=addCalendarDays(cursor,7);\n        weekIndex++;\n      }\n      return pages;\n    }\n\n    function pdfCalendarTaskLabel(task){\n      const activity=String(task.activity||'').replace(/^(?:Teoria|Exercícios|Revisão)\\s*-\\s*/i,'');\n      return `${task.start||''} ${task.subject||'Estudo'} • ${activity}`.trim();\n    }\n\n    function pdfBuildDaysStylePage(page,pageIndex,pageCount){\n      const commands=[];\n      const chrome=pdfDrawStyleChrome(commands,pageIndex,pageCount,`CALENDÁRIO POR QUANTIDADE DE DIAS · SEMANA ${page.weekIndex+1}`);\n      const {width,margin}=PDF_PAGE;\n      const gap=5;\n      const top=chrome.bodyTop;\n      const bottom=chrome.bodyBottom+4;\n      const cellHeight=top-bottom;\n      const cellWidth=(width-margin*2-gap*6)/7;\n      const totalDays=state.adminPlanDays||state.adminPersonalization?.planDays||0;\n      const weekStart=page.items[0]?.date;\n      const weekEnd=page.items[6]?.date;\n      if(weekStart&&weekEnd){\n        const range=`${weekStart.toLocaleDateString('pt-BR')} a ${weekEnd.toLocaleDateString('pt-BR')}`;\n        pdfText(commands,width-margin-220,top+14,range,8.3,true,PDF_COLORS.muted,'right',220);\n      }\n\n      page.items.forEach((day,col)=>{\n        const x=margin+col*(cellWidth+gap);\n        const simulation=day.tasks.some(task=>String(task.type||'').toLowerCase().includes('simulado'));\n        const fill=!day.inRange?PDF_COLORS.soft:(simulation?PDF_COLORS.pendingSoft:PDF_COLORS.white);\n        const border=simulation?PDF_COLORS.gold:PDF_COLORS.line;\n        pdfRect(commands,x,bottom,cellWidth,cellHeight,fill,border,simulation?1.15:.7);\n        const headFill=!day.inRange?PDF_COLORS.line:(simulation?PDF_COLORS.gold:PDF_COLORS.navy);\n        pdfRect(commands,x,top-31,cellWidth,31,headFill,null,0);\n        const dayName=DAYS[(day.date.getDay()+6)%7]||'';\n        pdfText(commands,x+6,top-12,dayName.toUpperCase(),6.6,true,day.inRange?PDF_COLORS.white:PDF_COLORS.muted);\n        pdfText(commands,x+6,top-24,day.date.toLocaleDateString('pt-BR'),7.2,true,day.inRange?(simulation?PDF_COLORS.navy:PDF_COLORS.white):PDF_COLORS.muted);\n        if(day.inRange&&day.planIndex>=0){\n          pdfText(commands,x+cellWidth-52,top-12,`DIA ${day.planIndex+1}/${totalDays}`,6.1,true,day.inRange?PDF_COLORS.white:PDF_COLORS.muted,'right',46);\n        }\n        let y=top-43;\n        if(!day.inRange){\n          pdfText(commands,x+6,y,'FORA DO PERÍODO',6.4,true,PDF_COLORS.muted);\n          return;\n        }\n        if(!day.tasks.length){\n          pdfText(commands,x+6,y,'SEM ESTUDO',7.2,true,PDF_COLORS.muted);\n          pdfText(commands,x+6,y-13,'Descanso / dia livre',6.2,false,PDF_COLORS.muted);\n          return;\n        }\n        if(simulation){\n          const task=day.tasks[0];\n          pdfText(commands,x+6,y,'SIMULADO',8,true,PDF_COLORS.goldDark);\n          const simLines=pdfWrapText(task.activity||task.subject,cellWidth-12,6.6,5,true);\n          simLines.forEach((line,index)=>pdfText(commands,x+6,y-15-index*9,line,6.6,index===0,PDF_COLORS.text));\n          if(task.start) pdfText(commands,x+6,y-15-simLines.length*9,`${task.start}${task.end?`–${task.end}`:''}`,6.4,true,PDF_COLORS.muted);\n          return;\n        }\n        const many=day.tasks.length>11;\n        const font=many?5.15:5.65;\n        const rowHeight=many?Math.max(8.6,Math.min(12,(cellHeight-47)/day.tasks.length)):Math.max(13,Math.min(22,(cellHeight-47)/day.tasks.length));\n        const showTwoLines=!many&&rowHeight>=17;\n        for(const task of day.tasks){\n          if(y<bottom+9) break;\n          if(showTwoLines){\n            const head=`${task.start||''} ${task.subject||'Estudo'}`.trim();\n            pdfText(commands,x+5,y,pdfWrapText(head,cellWidth-10,font,1,true)[0],font,true,PDF_COLORS.navy);\n            const activity=String(task.activity||'').replace(/^(?:Teoria|Exercícios|Revisão)\\s*-\\s*/i,'');\n            pdfText(commands,x+5,y-7.2,pdfWrapText(activity,cellWidth-10,font-.25,1,false)[0],font-.25,false,PDF_COLORS.text);\n          }else{\n            pdfText(commands,x+5,y,pdfWrapText(pdfCalendarTaskLabel(task),cellWidth-10,font,1,false)[0],font,false,PDF_COLORS.text);\n          }\n          y-=rowHeight;\n        }\n      });\n      return {content:commands.join('\\n'),button:chrome.button};\n    }\n\n    function pdfPrepareByStyle''','calendar functions')

# PDF mensal/por dias em A4 horizontal, restaura dimensões ao terminar.
sub(r'''    function buildSchedulePdfBytes\(\)\{.*?\n    \}\n\n    function exportPdf''', '''    function buildSchedulePdfBytes(){\n      pdfApplySelectedTheme();\n      const original={width:PDF_PAGE.width,height:PDF_PAGE.height,margin:PDF_PAGE.margin};\n      const calendar=state.scheduleStyle==='monthly';\n      if(calendar){\n        PDF_PAGE.width=841.89;\n        PDF_PAGE.height=595.28;\n        PDF_PAGE.margin=30;\n      }\n      try{\n        const prepared=pdfPrepareByStyle();\n        const hasIntro=Boolean(state.adminGenerated&&state.studentName);\n        const totalPages=prepared.pages.length+(hasIntro?1:0);\n        const pageDefinitions=[];\n        if(hasIntro) pageDefinitions.push(pdfBuildAdminIntroPageContent(0,totalPages));\n        let offset=0;\n        prepared.pages.forEach((page,index)=>{\n          const pageIndex=index+(hasIntro?1:0);\n          pageDefinitions.push(pdfBuildStyleDefinition(prepared.kind,page,pageIndex,totalPages,offset));\n          if(prepared.kind==='cycle') offset+=page.length;\n        });\n        return pdfBuildBinary(pageDefinitions);\n      }finally{\n        PDF_PAGE.width=original.width;\n        PDF_PAGE.height=original.height;\n        PDF_PAGE.margin=original.margin;\n      }\n    }\n\n    function exportPdf''','build pdf landscape')

